fn sinf(a: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let i: i32 = (a >> 3) & 31;
    let f: i32 = a & 7;
    let s0: i32 = tab[i];
    let s1: i32 = tab[(i + 1) & 31];
    s0 + (s1 - s0) * f / 8
}

fn cosf(a: i32) -> i32 {
    sinf(a + 64)
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let m: i32 = if w < h { w } else { h };
    let big: i32 = m / 2 - 30;
    let k: i32 = 2 + (t / 120) % 5;
    let pal = [0xff9de2, 0xffd166, 0x9df2ff, 0xb0ff9d];
    host::display::clear(0x070310);
    let mut a: i32 = 0;
    while a < 256 {
        let mut pet: i32 = sinf(a * k);
        if pet < 0 { pet = 0 - pet; }
        let rr: i32 = pet * big / 127;
        let x: i32 = cx + cosf(a) * rr / 127;
        let y: i32 = cy + sinf(a) * rr / 127;
        host::display::fill_rect(x - 1, y - 1, 3, 3, pal[(a >> 6) & 3]);
        a = a + 1;
    }
    host::display::draw_string(8, h - 24, "PETALS", 0x554466, 2);
    host::display::draw_number(104, h - 24, k, 0x554466, 2);
    host::display::present();
}
